    private void feed_table(boolean autombox) {
        new AutoMBox(getTitle(), autombox) {
            @Override
            public void do_stuff() throws Exception {
                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                ignoreSelectionChanges = true;
                // AI modification end
                tm.clear();
                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                ignoreSelectionChanges = false;
                // AI modification end

                DBBookingLine bookingline = new DBBookingLine();
                Transaction trans = getTransaction();

                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                // Includes direct links (BILL2BOOKINGLINE) and indirect event member bills.
                Map<Integer, Set<Integer>> billsPerBookingLine =
                        BillBookingLineHelper.fetchBillsPerBookingLine(trans, mainwin.getBPIdx());
                Set<Integer> blWithBill = billsPerBookingLine.keySet();
                // AI modification end

                StringBuilder sql = new StringBuilder();
                sql.append("where ").append(trans.markColumn(bookingline.bp_idx)).append(" = ").append(mainwin.getBPIdx());
                sql.append(" and ").append(trans.markColumn(bookingline.splitpos)).append(" = 0 ");

                if (jCIn.isSelected()) {
                    sql.append(" and ").append(trans.markColumn(bookingline.amount)).append(" >= 0 ");
                }
                if (jCOut.isSelected()) {
                    sql.append(" and ").append(trans.markColumn(bookingline.amount)).append(" <= 0 ");
                }
                if (jCUnassigned.isSelected()) {
                    sql.append(" and ").append(trans.markColumn(bookingline.assigned)).append(" = 0 ");
                }
                if (jCAssigned.isSelected()) {
                    sql.append(" and ").append(trans.markColumn(bookingline.assigned)).append(" = 1 ");
                }

                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                AccountClassDescr billFilter = (AccountClassDescr) jCBillAssignedFilter.getSelectedItem();
                if (billFilter != null && billFilter.filterIdx != 0) {
                    StringBuilder billIds = new StringBuilder();
                    for (Integer id : blWithBill) {
                        if (billIds.length() > 0) {
                            billIds.append(",");
                        }
                        billIds.append(id);
                    }

                    if (billFilter.filterIdx == 1) {
                        // assigned: only booking lines with at least one bill
                        if (blWithBill.isEmpty()) {
                            sql.append(" and 1 = 0 ");
                        } else {
                            sql.append(" and ").append(trans.markColumn(bookingline.idx))
                               .append(" in ( ").append(billIds).append(" ) ");
                        }
                    } else if (billFilter.filterIdx == -1) {
                        // unassigned: only booking lines without any bill
                        if (!blWithBill.isEmpty()) {
                            sql.append(" and ").append(trans.markColumn(bookingline.idx))
                               .append(" not in ( ").append(billIds).append(" ) ");
                        }
                    }
                }
                // AI modification end

                sql.append(DateFilter.getVonBisFilter(trans,
                        jCFrom.isSelected() ? filter_date_from : null,
                        jCTill.isSelected() ? filter_date_till : null,
                        bookingline.date));

                AccountClassDescr acFilter = (AccountClassDescr) jCAccountClassFilter.getSelectedItem();
                if (acFilter != null) {
                    if (acFilter.filterIdx == -1) {
                        sql.append(" and ").append(trans.markColumn(bookingline.account_class_idx)).append(" = 0 ");
                    } else if (acFilter.filterIdx > 0) {
                        sql.append(" and ").append(trans.markColumn(bookingline.account_class_idx)).append(" = ").append(acFilter.filterIdx).append(" ");
                    }
                }

                sql.append(" order by ").append(trans.markColumn(bookingline.date));

                values = trans.fetchTable2(bookingline, sql.toString());

                for (DBBookingLine entry : values) {
                    tm.add(entry);
                }

                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                for (int i = 0; i < values.size(); i++) {
                    DBBookingLine entry = values.get(i);
                    if (entry.idx.getValue() != null && blWithBill.contains(entry.idx.getValue())) {
                        for (var col : entry.getAllValues()) {
                            tm.setCellColor(col, i, BILL_ASSIGNED_COLOR);
                        }
                    }
                }
                // AI modification end

                // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
                tmBills.clear();
                bills_values.clear();
                directLinksByBillIdx.clear();
                jTSumBills.setText("");
                updateUploadBillButtonState();
                updateUnassignBillButtonState();
                // AI modification end
            }
        };
    }

