    private void jBAssignActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBAssignActionPerformed
        AccountClassDescr descr = (AccountClassDescr) jCAccountClassAssign.getSelectedItem();
        if (descr == null) {
            return;
        }

        int[] selectedViewRows = jTContent.getSelectedRows();
        if (selectedViewRows.length == 0) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "No rows selected.", "Info", javax.swing.JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        // convert view rows to model rows before any table refresh
        int[] modelRows = new int[selectedViewRows.length];
        for (int i = 0; i < selectedViewRows.length; i++) {
            modelRows[i] = jTContent.convertRowIndexToModel(selectedViewRows[i]);
        }

        new AutoMBox(getTitle()) {
            @Override
            public void do_stuff() throws Exception {
                Transaction trans = getTransaction();
                // AI-modified start: wrap in try/catch to rollback on failure
                try {
                    for (int modelRow : modelRows) {
                        if (modelRow < 0 || modelRow >= values.size()) {
                            continue;
                        }
                        DBBookingLine bl = values.get(modelRow);
                        if (descr.accountClass != null) {
                            bl.account_class_idx.loadFromCopy(descr.accountClass.idx.getValue());
                            bl.account_class.loadFromString(descr.accountClass.name.toString());
                        } else {
                            bl.account_class_idx.loadFromCopy(0);
                            bl.account_class.loadFromString("");
                        }
                        DefaultInsertOrUpdater.insertOrUpdateValuesWithPrimKey(trans, bl);
                    }
                    trans.commit();
                } catch (Exception ex) {
                    trans.rollback();
                    throw ex;
                }
                // AI-modified end
                feed_table(false);
            }
        };
    }//GEN-LAST:event_jBAssignActionPerformed

    // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
    private void jBUploadBillActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBUploadBillActionPerformed
        int selectedViewRow = jTContent.getSelectedRow();
        if (selectedViewRow < 0 || jTContent.getSelectedRowCount() != 1) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "Please select exactly one booking line.", "Info",
                    javax.swing.JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        int modelRow = jTContent.convertRowIndexToModel(selectedViewRow);
        if (modelRow < 0 || modelRow >= values.size()) {
            return;
        }

        final DBBookingLine bookingLine = values.get(modelRow);
        final Integer bookingLineIdx = bookingLine.idx.getValue();

        UploadExternalBill uploadBill = new UploadExternalBill(mainwin, null, bookingLineIdx);
        uploadBill.registerOnCloseListener(new Runnable() {
            @Override
            public void run() {
                feed_table();
                selectBookingLineById(bookingLineIdx);
            }
        });
        invokeDialogUnique(uploadBill);
    }//GEN-LAST:event_jBUploadBillActionPerformed
    // AI modification end

    // AI modification start (GitHub Copilot / DeepSeek V4 Pro)
    private void jBUnassignBillActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBUnassignBillActionPerformed
        final Integer bookingLineIdx = getSelectedBookingLineIdx();
        final Integer billIdx = getSelectedBillIdx();
        if (bookingLineIdx == null || billIdx == null) {
            return;
        }

        final DBBill2BookingLine link = directLinksByBillIdx.get(billIdx);
        if (link == null) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    MlM("This bill is assigned indirectly via the event member and cannot be removed here."),
                    MlM("Remove bill assignment"),
                    javax.swing.JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        Object[] options = {
            MlM("Remove assignment only"),
            MlM("Remove and cancel invoice"),
            MlM("Cancel")
        };

        int choice = javax.swing.JOptionPane.showOptionDialog(this,
                MlM("What should happen with the invoice?"),
                MlM("Remove bill assignment"),
                javax.swing.JOptionPane.YES_NO_CANCEL_OPTION,
                javax.swing.JOptionPane.QUESTION_MESSAGE,
                null,
                options,
                options[0]);

        if (choice != 0 && choice != 1) {
            return;
        }

        final boolean cancelBill = (choice == 1);

        new AutoMBox(getTitle()) {
            @Override
            public void do_stuff() throws Exception {
                Transaction trans = getTransaction();
                try {
                    trans.deleteWithPrimaryKey(link);

                    if (cancelBill) {
                        DBBill bill = new DBBill();
                        bill.idx.loadFromCopy(billIdx);
                        if (trans.fetchTableWithPrimkey(bill)) {
                            bill.state.handler.setValue(DBBill.State.CANCELED.ordinal());
                            bill.cancel_reason.loadFromString(MlM("Unassigned in Operational"));
                            DefaultInsertOrUpdater.insertOrUpdateValuesWithPrimKey(
                                    trans, bill, bill.hist, root.getUserName());
                        }
                    }

                    trans.commit();
                } catch (Exception ex) {
                    trans.rollback();
                    throw ex;
                }
            }
        };

        feed_table();
        selectBookingLineById(bookingLineIdx);
    }//GEN-LAST:event_jBUnassignBillActionPerformed
    // AI modification end

